<?php $pageTitle=page_title('Manage markets'); $page='admin-markets'; ?>
<div class="dashboard-head reveal"><div><span class="eyebrow">Pickup network</span><h1>Markets</h1><p>Manage community pickup points, hours, days, and map coordinates.</p></div><a class="btn" href="<?= e(url('admin-market-form')) ?>"><?= icon('plus') ?> Add market</a></div>
<div class="market-grid"><?php foreach($markets as $market): ?><article class="card card-pad"><div style="display:flex;justify-content:space-between;gap:10px"><span class="pill <?= $market['status']==='active'?'pill-lime':'pill-gray' ?>"><?= e(ucfirst($market['status'])) ?></span><?= status_pill($market['status']) ?></div><h2 style="margin:16px 0 5px;color:var(--green-950);font-size:1.2rem"><?= e($market['name']) ?></h2><p class="text-muted" style="font-size:.84rem"><?= e($market['address']) ?></p><div class="spec-list" style="grid-template-columns:1fr 1fr;margin:16px 0"><li><strong><?= e($market['day_label']) ?></strong><span>Operating days</span></li><li><strong><?= e(date('g:i A',strtotime($market['open_time']))) ?> – <?= e(date('g:i A',strtotime($market['close_time']))) ?></strong><span>Hours</span></li><li><strong><?= (int)$market['farmer_count'] ?></strong><span>Active farmers</span></li><li><strong><?= (int)$market['order_count'] ?></strong><span>Orders</span></li></div><div style="display:flex;gap:7px;flex-wrap:wrap"><a class="btn btn-sm" href="<?= e(url('admin-market-form',['id'=>$market['id']])) ?>"><?= icon('edit') ?> Edit</a><a class="btn btn-light btn-sm" href="<?= e(url('market',['id'=>$market['id']])) ?>" target="_blank" rel="noopener">Preview ↗</a><?php if($market['status']==='active'): ?><form method="post" action="<?= e(url('admin-market-delete')) ?>" data-confirm="Deactivate this market? Historical orders will be preserved."><?= csrf_field() ?><input type="hidden" name="market_id" value="<?= (int)$market['id'] ?>"><button class="btn btn-danger btn-sm" type="submit">Deactivate</button></form><?php endif; ?></div></article><?php endforeach; ?></div>
